const response = $input.first().json;
const updates = response.result || [];
const ADMIN_ID = 6485376162;
const results = [];
let maxOffset = $('Get Offset').item.json.last_offset || 0;

for (const update of updates) {
  if (update.update_id !== undefined && update.update_id >= maxOffset) {
    maxOffset = update.update_id + 1;
  }

  const msg = update.message;
  if (!msg || !msg.text) continue;

  const text = msg.text.trim();
  const chatId = msg.chat?.id;
  const fromId = msg.from?.id;

  if (fromId !== ADMIN_ID) continue;

  const parts = text.split(/\s+/);
  const cmd = parts[0].replace('/', '').toLowerCase();
  const VALID = ['start','help','invite','status','resend','suspend','unsuspend','list','allsubs','count','allcodes','available','usedcodes','search','dbstatus','delsub','delcode','pending','verify','reject','incident','resolve','delinc'];

  results.push({
    json: {
      command: VALID.includes(cmd) ? cmd : 'unknown',
      args: parts.slice(1),
      chatId: chatId,
      fromId: fromId,
      rawText: text,
      nextOffset: maxOffset
    }
  });
}

// Always return at least one item with the offset, even if no commands
if (results.length === 0) {
  results.push({ json: { command: '__noop__', nextOffset: maxOffset } });
}

return results;

